T-EN-101 (à vérifier)","catalogue_groupe":"professionnel","public_cible":"professionnel","caracteristiques":{"surface_reference_m2":300,"prix_fourniture_unitaire_ht_m2":12.0,"prix_pose_unitaire_ht_m2":10.0,"prix_fourniture_ht":3600,"forfait_pose_ht":3000,"total_ht_reference":6600,"resistance_thermique_min_m2K_W":7,"cee_montant_eur":null,"cee_eligibilite":"À vérifier, aucun montant CEE renseigné dans le tableau.","source_tarifs":"Catalogue professionnel fourni par Reno Soluces — 20/10/2026","marques_suggerees":["ISOVER","SOPREMA"],"modele_exact_a_confirmer":true}},{"categorie":"isolation_combles_pro","nom":"Isolation des rampants / toiture inclinée — 300 m²","marque":"ISOVER / SOPREMA","reference":"PRO-BAT-EN-101-RAMPANTS-300","description":"Montant CEE non chiffré dans le document source ; fiche à vérifier.","unite":"forfait","prix_ht":7500,"pose_ht":7500,"tva":20,"eligible_mpr":false,"eligible_cee":false,"fiche_cee":"BAT-EN-101 (à vérifier)","catalogue_groupe":"professionnel","public_cible":"professionnel","caracteristiques":{"surface_reference_m2":300,"prix_fourniture_unitaire_ht_m2":25.0,"prix_pose_unitaire_ht_m2":25.0,"prix_fourniture_ht":7500,"forfait_pose_ht":7500,"total_ht_reference":15000,"resistance_thermique_min_m2K_W":null,"cee_montant_eur":null,"cee_eligibilite":"À vérifier, aucun montant CEE renseigné dans le tableau.","source_tarifs":"Catalogue professionnel fourni par Reno Soluces — 20/10/2026","marques_suggerees":["ISOVER","SOPREMA"],"modele_exact_a_confirmer":true}}]$products$::jsonb) LOOP
    SELECT id INTO v_id FROM public.catalogue_produits
    WHERE entreprise_id = v_entreprise
      AND ((COALESCE(p->>'reference','') <> '' AND reference = p->>'reference')
        OR (categorie = p->>'categorie' AND lower(nom) = lower(p->>'nom')))
    ORDER BY CASE WHEN COALESCE(p->>'reference','') <> '' AND reference = p->>'reference' THEN 0 ELSE 1 END
    LIMIT 1;

    IF v_id IS NULL THEN
      INSERT INTO public.catalogue_produits (
        entreprise_id,categorie,nom,marque,reference,description,caracteristiques,
        prix_unitaire_ht,forfait_pose_ht,unite,tva_taux,eligible_mpr,eligible_cee,fiche_cee,actif,
        public_cible,catalogue_groupe
      ) VALUES (
        v_entreprise,p->>'categorie',p->>'nom',COALESCE(p->>'marque',''),COALESCE(p->>'reference',''),
        COALESCE(p->>'description',''),COALESCE(p->'caracteristiques','{}'::jsonb),
        COALESCE((p->>'prix_ht')::numeric,0),COALESCE((p->>'pose_ht')::numeric,0),COALESCE(p->>'unite','unite'),
        COALESCE((p->>'tva')::numeric,20),COALESCE((p->>'eligible_mpr')::boolean,false),COALESCE((p->>'eligible_cee')::boolean,false),
        COALESCE(p->>'fiche_cee',''),true,COALESCE(p->>'public_cible','particulier'),COALESCE(p->>'catalogue_groupe','particulier')
      );
    ELSE
      UPDATE public.catalogue_produits SET
        categorie = p->>'categorie', nom = p->>'nom', marque = COALESCE(NULLIF(p->>'marque',''),marque),
        reference = COALESCE(NULLIF(p->>'reference',''),reference), description = COALESCE(NULLIF(p->>'description',''),description),
        caracteristiques = COALESCE(caracteristiques,'{}'::jsonb) || COALESCE(p->'caracteristiques','{}'::jsonb),
        prix_unitaire_ht = CASE WHEN COALESCE((p->'caracteristiques'->>'prix_a_renseigner')::boolean,false) THEN prix_unitaire_ht ELSE COALESCE((p->>'prix_ht')::numeric,prix_unitaire_ht) END,
        forfait_pose_ht = CASE WHEN COALESCE((p->'caracteristiques'->>'forfait_pose_a_renseigner')::boolean,false) THEN forfait_pose_ht ELSE COALESCE((p->>'pose_ht')::numeric,forfait_pose_ht) END,
        unite = COALESCE(p->>'unite',unite), tva_taux = COALESCE((p->>'tva')::numeric,tva_taux),
        eligible_mpr = COALESCE((p->>'eligible_mpr')::boolean,false), eligible_cee = COALESCE((p->>'eligible_cee')::boolean,false),
        fiche_cee = COALESCE(p->>'fiche_cee',''), public_cible = COALESCE(p->>'public_cible','particulier'),
        catalogue_groupe = COALESCE(p->>'catalogue_groupe','particulier'), actif = true
      WHERE id = v_id;
    END IF;
    v_id := NULL;
  END LOOP;

  -- Reclasser les deux accessoires Comwatt dans Panneaux photovoltaïques.
  UPDATE public.catalogue_produits SET
    categorie='photovoltaique', catalogue_groupe='particulier', public_cible='particulier', actif=true,
    caracteristiques=COALESCE(caracteristiques,'{}'::jsonb) || '{"famille":"Accessoire photovoltaïque / pilotage énergétique","classement_catalogue":"Panneaux photovoltaïques"}'::jsonb
  WHERE entreprise_id=v_entreprise AND reference IN ('MODULE-SG-READY','SMARTPLUG-GEN4');

  -- Les anciennes batteries et les kits de stockage doivent rester visibles dans la famille photovoltaïque.
  UPDATE public.catalogue_produits SET categorie='photovoltaique', catalogue_groupe='particulier', public_cible='particulier', actif=true
  WHERE entreprise_id=v_entreprise AND (
    categorie='batterie_stockage' OR lower(nom) LIKE '%batterie de stockage%' OR lower(nom) LIKE '%stockage batterie%' OR lower(nom) LIKE '%batterie additionnelle%' OR lower(nom) LIKE '%kit photovoltaïque%batterie%'
  );

  -- Classer les visites techniques existantes, y compris celles qui avaient été rangées dans « autre ».
  UPDATE public.catalogue_produits SET
    categorie = CASE
      WHEN lower(nom) LIKE '%diagnostic%' OR lower(nom) LIKE '%3cl%' THEN 'vt_diagnostic_3cl'
      WHEN lower(nom) LIKE '%produit%' OR lower(nom) LIKE '%photovolta%' OR lower(nom) LIKE '%panneau solaire%' OR lower(nom) LIKE '%pv %' OR lower(nom) LIKE 'vt pv%' THEN 'vt_produit'
      ELSE 'vt_complete'
    END,
    catalogue_groupe='visite_technique',
    public_cible=CASE WHEN lower(nom) LIKE '%photovolta%' OR lower(nom) LIKE '%panneau solaire%' OR lower(nom) LIKE '%pv %' OR lower(nom) LIKE 'vt pv%' THEN 'professionnel' ELSE 'particulier' END,
    caracteristiques=COALESCE(caracteristiques,'{}'::jsonb) || jsonb_build_object('ancienne_categorie',categorie,'classement_visite_technique_2026_10_20',true),
    actif=true
  WHERE entreprise_id=v_entreprise AND categorie='autre'
    AND (lower(nom) LIKE '%visite technique%' OR lower(nom) LIKE '%visites techniques%' OR lower(nom) LIKE 'vt %' OR lower(nom) LIKE '%diagnostic%' OR lower(nom) LIKE '%3cl%');

  UPDATE public.catalogue_produits SET
    catalogue_groupe='visite_technique',
    public_cible=CASE WHEN lower(nom) LIKE '%photovolta%' OR lower(nom) LIKE '%panneau solaire%' OR lower(nom) LIKE '%pv %' OR lower(nom) LIKE 'vt pv%' THEN 'professionnel' ELSE 'particulier' END,
    actif=true
  WHERE entreprise_id=v_entreprise AND categorie IN ('vt_complete','vt_produit','vt_diagnostic_3cl');

  -- Les configurations PV pro, isolation pro, HP flottante et destratification sont exclusivement professionnelles.
  UPDATE public.catalogue_produits SET catalogue_groupe='professionnel',public_cible='professionnel'
  WHERE entreprise_id=v_entreprise AND categorie IN ('hp_flottante','destratificateur','isolation_toiture_pro','isolation_combles_pro','pro_photovoltaique')
    AND (reference LIKE 'PRO-%' OR lower(nom) LIKE '%tertiaire%' OR lower(nom) LIKE '%professionnel%');
END $$;
